```tsx
import { useId } from "react";
import type { ReactElement } from "react";
import "./SettingsToggleRow.css";

export interface SettingsToggleRowProps {
  label: string;
  hint: string;
  checked: boolean;
  onChange: (checked: boolean) => void;
}

export function SettingsToggleRow({
  label,
  hint,
  checked,
  onChange,
}: SettingsToggleRowProps): ReactElement {
  const labelId = useId();
  const hintId = useId();

  return (
    <div className="settings-toggle-row">
      <div className="settings-toggle-row__text">
        <span id={labelId} className="settings-toggle-row__label">
          {label}
        </span>
        <span id={hintId} className="settings-toggle-row__hint">
          {hint}
        </span>
      </div>
      <button
        type="button"
        className="settings-toggle-row__switch"
        aria-pressed={checked}
        aria-labelledby={labelId}
        aria-describedby={hintId}
        onClick={() => onChange(!checked)}
      >
        <span className="settings-toggle-row__knob" aria-hidden="true" />
      </button>
    </div>
  );
}
```

```css
.settings-toggle-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: clamp(0.75rem, 2vw, 1.25rem);
  padding: clamp(0.6rem, 1.2vw, 0.9rem) 0;
  border-bottom: 1px solid var(--hair);
  color: var(--ink);
  font: inherit;
}

.settings-toggle-row__text {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  min-width: 0;
  flex: 1 1 auto;
}

.settings-toggle-row__label {
  display: block;
  color: var(--ink);
  font: inherit;
  font-size: clamp(0.9rem, 0.8rem + 0.4vw, 1.05rem);
}

.settings-toggle-row__hint {
  display: block;
  min-width: 0;
  color: var(--muted);
  font: inherit;
  font-size: clamp(0.75rem, 0.7rem + 0.25vw, 0.9rem);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.settings-toggle-row__switch {
  position: relative;
  box-sizing: border-box;
  flex: 0 0 auto;
  width: 2.75rem;
  height: 1.5rem;
  margin: 0;
  padding: 0;
  border: 1px solid var(--muted);
  border-radius: 999px;
  background: transparent;
  font: inherit;
  cursor: pointer;
  transition:
    background-color 180ms ease,
    border-color 180ms ease;
}

.settings-toggle-row__switch[aria-pressed="true"] {
  background: var(--myelin);
  border-color: var(--myelin);
}

.settings-toggle-row__knob {
  position: absolute;
  top: 50%;
  left: 0.1875rem;
  width: 1.125rem;
  height: 1.125rem;
  border-radius: 50%;
  background: var(--muted);
  transform: translate(0, -50%);
  transition:
    transform 180ms ease,
    background-color 180ms ease;
}

.settings-toggle-row__switch[aria-pressed="true"] .settings-toggle-row__knob {
  background: var(--slide);
  transform: translate(1.125rem, -50%);
}

:root[data-motion="reduce"] .settings-toggle-row__switch,
:root[data-motion="reduce"] .settings-toggle-row__knob {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .settings-toggle-row__switch,
  .settings-toggle-row__knob {
    transition: none;
  }
}
